scripts.parity_functions:
def tag_domain(records, row):
    for record in records:
        altitude = record.get('alt_ft')
        record['domain_hint'] = 'AIR' if altitude else row.get('default_domain')
    return records


def drop_flagged(records, row):
    return [record for record in records if not record.get('flagged')]

scripts.parity_units:
import math


def to_radians(value):
    return math.radians(float(value))


def feet_to_meters(value):
    return float(value) * 0.3048
